if (polygon.size() < 3) return true;

typedef typename std::iterator_traits<decltype(polygon.begin())>::value_type Point;
typedef CGAL::Kernel_traits<Point> KTraits;
typedef typename KTraits::Kernel Kernel;

Kernel kernel;
bool is_ccw = kernel.is_ccw_strongly_convex_2(polygon.begin(), polygon.end(), kernel);
bool is_cw = kernel.is_cw_strongly_convex_2(polygon.begin(), polygon.end(), kernel);

return is_ccw || is_cw;

